CREATE TABLE ibexa_content_name (contentobject_id INT DEFAULT 0 NOT NULL, content_version INT DEFAULT 0 NOT NULL, content_translation VARCHAR(20) DEFAULT '' NOT NULL, language_id BIGINT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, real_translation VARCHAR(20) DEFAULT NULL, INDEX ibexa_content_name_lang_id (language_id), INDEX ibexa_content_name_cov_id (content_version), INDEX ibexa_content_name_name (name(191)), PRIMARY KEY(contentobject_id, content_version, content_translation)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
